//! «О программе → Лицензии» (T6.6, NFR-LIC-001, `08` §3): the third-party notices generated by
//! `tools/notices.py` into `assets/legal/notices.json` — every Rust crate and JS package inside
//! Сиртон, the font (full OFL text), the models, data, presets and the services' terms. Embedded
//! (works offline and without the installer's folder); the screen asks once, when opened.

use serde::{Deserialize, Serialize};

const NOTICES: &str = include_str!("../../../../assets/legal/notices.json");

#[derive(Debug, Clone, Serialize, Deserialize, specta::Type)]
pub struct NoticeSection {
    pub title: String,
    pub license: String,
    /// Packages under this text (`name version`); empty for the font, models, data.
    pub items: Vec<String>,
    pub text: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, specta::Type)]
pub struct Notices {
    pub rust: u32,
    pub js: u32,
    pub sections: Vec<NoticeSection>,
}

#[tauri::command(async)]
#[specta::specta]
pub fn legal_notices() -> Notices {
    serde_json::from_str(NOTICES).unwrap_or(Notices {
        rust: 0,
        js: 0,
        sections: Vec::new(),
    })
}

#[cfg(test)]
mod tests {
    #[test]
    fn the_notices_parse_and_carry_the_font_and_every_text() {
        let n = super::legal_notices();
        assert!(n.rust > 300 && n.js > 10, "{} {}", n.rust, n.js);
        assert!(
            n.sections
                .iter()
                .any(|s| s.text.contains("SIL OPEN FONT LICENSE"))
        );
        assert!(n.sections.iter().all(|s| !s.text.trim().is_empty()));
        // A package group never shows a bare license id instead of its text.
        assert!(
            n.sections
                .iter()
                .filter(|s| !s.items.is_empty())
                .all(|s| s.text != s.license)
        );
    }
}
